   258  // For virtual mode, returns true if all reads on mapped regions are successful
   259  // and complete.
   260  // For physical mode, the interface is broken because the actual read bytes are
   261  // not available. This requires fixes in all call sites.
   262  R_API bool r_io_read_at(RIO *io, ut64 addr, ut8 *buf, int len) {
   263          r_return_val_if_fail (io && buf && len >= 0, false);
   264          if (len == 0) {
   265                  return false;
   266          }
   267          if (io->mask) {
   268                  ut64 p = addr;
   269                  size_t q = 0;
   270                  while (q < len) {
   271                          p &= io->mask;
   272                          size_t sz = io->mask - p + 1;
   273                          size_t left = len - q;
   274                          if (sz > left) {
   275                                  sz = left;
   276                          }
   277                          if (!internal_r_io_read_at (io, p, buf + q, sz)) {
   278                                  return false;
   279                          }
   280                          q += sz;
   281                          p = 0;
   282                  }
   283                  return true;
   284          }
   285          return internal_r_io_read_at (io, addr, buf, len);
   286  }
